import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("a vendor with only an extracted W-9 can't be submitted yet", { tag: "@UI-08" }, async ({ factory, apiAs, pages, signIn }) => {
  // Arrange
  const vendor = await factory.vendor({ name: uniqueName("Partial Docs") });
  await factory.upload(vendor.id, "w9");
  const api = await apiAs("member");
  await expect
    .poll(
      async () => {
        const documents = await expectStatus<{ status: string }[]>(await api.get(`/api/vendors/${vendor.id}/documents`), 200);
        return documents.map((d) => d.status);
      },
      { message: "W-9 extraction finishes", timeout: 30_000 },
    )
    .toEqual(["extracted"]);
  await signIn("member");

  // Act
  await pages.vendor.goto(vendor.id);

  // Assert
  await expect(pages.vendor.document("w9")).toBeVisible();
  await expect(pages.vendor.submitButton).toBeDisabled();
  await expect(pages.vendor.stillNeeded(["insurance_certificate", "contract"])).toBeVisible();
});
